// Narration for the short cut, generated by the voice.ai text-to-speech API: one mp3 per line of LINES in pain/cut.mjs → pain/voice/.
//   node pain/voice.mjs [--force]
// Key: AI_VOICE_TOKEN in server/.env (or VOICE_AI_API_KEY in a git-ignored assets/video/remotion/.env). VOICE_AI_VOICE_ID overrides the voice.
// File names carry a hash of voice + text, so editing a line (or the voice) regenerates just that line; unchanged lines are kept.
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { LINES } from './cut.mjs';

const here = dirname(fileURLToPath(import.meta.url));
export const VOICE_DIR = join(here, 'voice');

/** "Ryan - South African": median pitch ≈ 88 Hz on the same sentence, the deepest of the public male voices (Dalton 119, Matt 132, Lachlan 134). */
export const DEFAULT_VOICE = '9556bcc7-ace2-4510-be5d-31f1165bcc87';

const WANTED = new Set(['VOICE_AI_API_KEY', 'AI_VOICE_TOKEN', 'VOICE_AI_VOICE_ID']);
function loadEnv() {
  for (const f of [join(here, '..', '.env'), join(here, '..', '..', '..', '..', 'server', '.env')]) {
    if (!existsSync(f)) continue;
    for (const line of readFileSync(f, 'utf8').split('\n')) {
      const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*?)\s*$/);
      if (m && WANTED.has(m[1]) && !(m[1] in process.env)) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '');
    }
  }
}
loadEnv();

const voiceId = () => process.env.VOICE_AI_VOICE_ID || DEFAULT_VOICE;
export const voicePath = (i) =>
  join(VOICE_DIR, `line-${i}-${createHash('sha1').update(`${voiceId()}|${LINES[i].say}`).digest('hex').slice(0, 8)}.mp3`);

/** The room. Real voices (the public voice.ai ones) saying ordinary things, mixed into a murmur and into reactions — noise made it hiss. */
const V = { ellie: 'd1bf0f33-8e0e-4fbf-acf8-45c3c6262513', lauren: 'c22f0e4c-e437-4877-9fce-09d33336ca92', emma: '44de4286-f7aa-4216-845f-807103e33ac8', matt: 'c9530f8a-dcb5-4db3-aed0-690694247a1a', alicia: 'e16986bd-1ce9-4c1c-88e7-bbe02b1340d1', dalton: '567bace0-2fee-4585-856d-292c8caf71db' };
export const CROWD = [
  { kind: 'chat', voice: V.lauren, say: 'So I told him, there is no way I am going to that.' },
  { kind: 'chat', voice: V.matt,   say: 'Did you see the game last night? It was unreal.' },
  { kind: 'chat', voice: V.alicia, say: 'Oh my god, I love this place, it is so cozy.' },
  { kind: 'chat', voice: V.dalton, say: 'Hey, can you pass me that drink over there?' },
  { kind: 'chat', voice: V.emma,   say: 'No way, you are kidding me, that is hilarious.' },
  { kind: 'chat', voice: V.ellie,  say: 'Let us grab another one before it gets crowded.' },
  { kind: 'react', voice: V.emma,   say: 'Wow.' },
  { kind: 'react', voice: V.matt,   say: 'Whoa, he is good!' },
  { kind: 'react', voice: V.alicia, say: 'That is amazing!' },
  { kind: 'react', voice: V.dalton, say: 'Play more!' },
  { kind: 'react', voice: V.lauren, say: 'Yeah!' },
  { kind: 'react', voice: V.ellie,  say: 'Whoo!' },
  { kind: 'react', voice: V.matt,   say: 'Encore!' },
  { kind: 'react', voice: V.alicia, say: 'Oh my god!' },
  { kind: 'react', voice: V.emma,   say: 'Oh no.' },
];
export const crowdPath = (i) =>
  join(VOICE_DIR, `crowd-${i}-${createHash('sha1').update(`${CROWD[i].voice}|${CROWD[i].say}`).digest('hex').slice(0, 8)}.mp3`);

async function tts(key, text, voice, file, force) {
  if (existsSync(file) && !force) return false;
  const body = { text, voice_id: voice, language: 'en', model: 'voiceai-tts-v1-latest', audio_format: 'mp3_44100_128' };
  for (let attempt = 1; ; attempt++) {                                      // the API answers 500 now and then; a retry goes through
    const res = await fetch('https://dev.voice.ai/api/v1/tts/speech', {
      method: 'POST', headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    if (res.ok) { writeFileSync(file, Buffer.from(await res.arrayBuffer())); return true; }
    if (res.status < 500 || attempt >= 4) throw new Error(`voice.ai ${res.status}: ${(await res.text()).slice(0, 300)}`);
    await new Promise((r) => setTimeout(r, 1500 * attempt));
  }
}

export async function generateVoice(force = false) {
  const key = process.env.VOICE_AI_API_KEY || process.env.AI_VOICE_TOKEN;
  if (!key) throw new Error('no voice.ai key: set AI_VOICE_TOKEN in server/.env or VOICE_AI_API_KEY in assets/video/remotion/.env');
  mkdirSync(VOICE_DIR, { recursive: true });
  for (let i = 0; i < LINES.length; i++) console.log(`voice: line ${i} ${(await tts(key, LINES[i].say, voiceId(), voicePath(i), force)) ? 'generated' : 'kept'}`);
  for (let i = 0; i < CROWD.length; i++) console.log(`voice: crowd ${i} ${(await tts(key, CROWD[i].say, CROWD[i].voice, crowdPath(i), force)) ? 'generated' : 'kept'}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  generateVoice(process.argv.includes('--force')).catch((e) => { console.error(e.message); process.exit(1); });
}
